INSERT INTO recipes_steps (recipe_id, step_order, step_type, content, quantity_value, quantity_unit, timer_hours, timer_minutes) VALUES ('dumplings', 3, 'instruction', '{"en": "Make dough: mix flour, egg, water and a pinch of salt. Knead and let rest for 30 minutes", "uk": "Зробіть тісто: змішайте борошно, яйце, воду та дрібку солі. Вимішайте та залиште на 30 хвилин", "ru": "Сделайте тесто: смешайте муку, яйцо, воду и щепотку соли. Вымесите и оставьте на 30 минут", "be": "Зрабіце цеста: змяшайце муку, яйка, ваду і дробку солі. Вымесіце і пакіньце на 30 хвілін"}', NULL, NULL, 0, 30);
