INSERT INTO recipes_steps (recipe_id, step_order, step_type, content, quantity_value, quantity_unit, timer_hours, timer_minutes) VALUES ('dumplings', 7, 'instruction', '{"en": "Grind pork, beef and onion together. Season with salt and pepper", "uk": "Пропустіть свинину, яловичину та цибулю через м''ясорубку. Приправте сіллю та перцем", "ru": "Пропустите свинину, говядину и лук через мясорубку. Приправьте солью и перцем", "be": "Прапусціце свініну, ялавічыну і цыбулю праз мясарубку. Прыпраўце соллю і перцам"}', NULL, NULL, NULL, NULL);
