INSERT INTO recipes_steps (recipe_id, step_order, step_type, content, quantity_value, quantity_unit, timer_hours, timer_minutes) VALUES ('dumplings', 9, 'instruction', '{"en": "Roll out dough, cut circles, place filling and seal edges. Boil dumplings in salted water for 7 minutes", "uk": "Розкачайте тісто, виріжте кружечки, покладіть начинку та заліпіть краї. Варіть пельмені у підсоленій воді 7 хвилин", "ru": "Раскатайте тесто, вырежьте кружочки, положите начинку и защипните края. Варите пельмени в подсоленной воде 7 минут", "be": "Раскачайце цеста, выражце кружочкі, пакладзіце начынне і зашчыпніце краі. Варыце пельмені ў падсоленай вадзе 7 хвілін"}', NULL, NULL, 0, 7);
