INSERT INTO recipes_steps (recipe_id, step_order, step_type, content, quantity_value, quantity_unit, timer_hours, timer_minutes) VALUES ('buckwheat_with_meat', 2, 'instruction', '{"en": "Cut pork into pieces and fry until golden brown", "uk": "Наріжте свинину шматочками та обсмажте до золотистої скоринки", "ru": "Нарежьте свинину кусочками и обжарьте до золотистой корочки", "be": "Нарэжце свініну кавалачкамі і абсмажце да залацістай скарынкі"}', NULL, NULL, 0, 15);
