INSERT INTO recipes_steps (recipe_id, step_order, step_type, content, quantity_value, quantity_unit, timer_hours, timer_minutes) VALUES ('buckwheat_with_meat', 5, 'instruction', '{"en": "Add chopped onion and grated carrot, fry for 5 minutes", "uk": "Додайте нарізану цибулю та терту моркву, смажте 5 хвилин", "ru": "Добавьте нарезанный лук и тёртую морковь, жарьте 5 минут", "be": "Дадайце нарэзаную цыбулю і цёртую моркву, смажце 5 хвілін"}', NULL, NULL, 0, 5);
