INSERT INTO recipes_steps (recipe_id, step_order, step_type, content, quantity_value, quantity_unit, timer_hours, timer_minutes) VALUES ('buckwheat_with_meat', 8, 'instruction', '{"en": "Add buckwheat, salt and water (1:2 ratio). Cover and simmer for 20 minutes", "uk": "Додайте гречку, сіль та воду (1:2). Накрийте кришкою та тушкуйте 20 хвилин", "ru": "Добавьте гречку, соль и воду (1:2). Накройте крышкой и тушите 20 минут", "be": "Дадайце грэчку, соль і ваду (1:2). Накрыйце вечкам і тушыце 20 хвілін"}', NULL, NULL, 0, 20);
