INSERT INTO recipes_steps (recipe_id, step_order, step_type, content, quantity_value, quantity_unit, timer_hours, timer_minutes) VALUES ('omelette', 4, 'instruction', '{"en": "Whisk eggs with milk and salt until combined", "uk": "Збийте яйця з молоком та сіллю до однорідності", "ru": "Взбейте яйца с молоком и солью до однородности", "be": "Узбіце яйкі з малаком і соллю да аднароднасці"}', NULL, NULL, NULL, NULL);
