INSERT INTO recipes_steps (recipe_id, step_order, step_type, content, quantity_value, quantity_unit, timer_hours, timer_minutes) VALUES ('omelette', 6, 'instruction', '{"en": "Melt butter in a pan over medium heat, pour in egg mixture and cook covered for 5-7 minutes", "uk": "Розтопіть масло на сковороді на середньому вогні, вилийте яєчну суміш та готуйте під кришкою 5-7 хвилин", "ru": "Растопите масло на сковороде на среднем огне, вылейте яичную смесь и готовьте под крышкой 5-7 минут", "be": "Разагрэйце масла на патэльні на сярэднім агні, выліце яечную сумесь і рыхтуйце пад вечкам 5-7 хвілін"}', NULL, NULL, 0, 7);
