INSERT INTO recipes_steps (recipe_id, step_order, step_type, content, quantity_value, quantity_unit, timer_hours, timer_minutes) VALUES ('vinaigrette', 6, 'instruction', '{"en": "Dice cucumbers and finely chop onion. Combine all vegetables", "uk": "Наріжте огірки кубиками та дрібно наріжте цибулю. Змішайте всі овочі", "ru": "Нарежьте огурцы кубиками и мелко нарежьте лук. Смешайте все овощи", "be": "Нарэжце агуркі кубікамі і дробна нарэжце цыбулю. Змяшайце ўсе гародніны"}', NULL, NULL, NULL, NULL);
