INSERT INTO recipes_steps (recipe_id, step_order, step_type, content, quantity_value, quantity_unit, timer_hours, timer_minutes) VALUES ('vinaigrette', 9, 'instruction', '{"en": "Season with sunflower oil and salt, toss gently", "uk": "Заправте соняшниковою олією та сіллю, обережно перемішайте", "ru": "Заправьте подсолнечным маслом и солью, аккуратно перемешайте", "be": "Запраўце сланечнікавым алеем і соллю, асцярожна перамяшайце"}', NULL, NULL, NULL, NULL);
